CREATE TRIGGER interview_receipt_immutable BEFORE UPDATE OR DELETE ON interview_receipt FOR EACH ROW EXECUTE FUNCTION interview_fact_immutable();
CREATE TRIGGER access_grant_source_approval_immutable BEFORE UPDATE OR DELETE ON access_grant_source_approval FOR EACH ROW EXECUTE FUNCTION interview_fact_immutable();
CREATE FUNCTION interview_owner_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='interview' THEN IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at OR NEW.author_subject_id IS DISTINCT FROM OLD.author_subject_id OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN RAISE EXCEPTION 'immutable interview owner' USING ERRCODE='23514'; END IF; END IF; IF TG_TABLE_NAME='note_head' THEN IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.interview_id IS DISTINCT FROM OLD.interview_id OR NEW.category IS DISTINCT FROM OLD.category THEN RAISE EXCEPTION 'immutable interview owner' USING ERRCODE='23514'; END IF; END IF; IF TG_TABLE_NAME='action_item' THEN IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.interview_id IS DISTINCT FROM OLD.interview_id OR NEW.category IS DISTINCT FROM OLD.category OR NEW.owner_kind IS DISTINCT FROM OLD.owner_kind OR NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id OR NEW.owner_employee_id IS DISTINCT FROM OLD.owner_employee_id OR NEW.due_date IS DISTINCT FROM OLD.due_date OR NEW.author_subject_id IS DISTINCT FROM OLD.author_subject_id OR NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN RAISE EXCEPTION 'immutable interview owner' USING ERRCODE='23514'; END IF; END IF; IF TG_TABLE_NAME='access_grant' THEN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.subject_id IS DISTINCT FROM OLD.subject_id OR NEW.capability IS DISTINCT FROM OLD.capability OR NEW.category IS DISTINCT FROM OLD.category OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_id IS DISTINCT FROM OLD.scope_id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.purpose IS DISTINCT FROM OLD.purpose OR NEW.object_ref IS DISTINCT FROM OLD.object_ref OR NEW.object_kind IS DISTINCT FROM OLD.object_kind OR NEW.object_employee_id IS DISTINCT FROM OLD.object_employee_id OR NEW.interview_id IS DISTINCT FROM OLD.interview_id OR NEW.note_head_id IS DISTINCT FROM OLD.note_head_id OR NEW.note_version_id IS DISTINCT FROM OLD.note_version_id OR NEW.action_item_id IS DISTINCT FROM OLD.action_item_id THEN RAISE EXCEPTION 'immutable interview owner' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_owner_immutable BEFORE UPDATE ON interview FOR EACH ROW EXECUTE FUNCTION interview_owner_immutable();
CREATE TRIGGER note_head_owner_immutable BEFORE UPDATE ON note_head FOR EACH ROW EXECUTE FUNCTION interview_owner_immutable();
CREATE TRIGGER action_item_owner_immutable BEFORE UPDATE ON action_item FOR EACH ROW EXECUTE FUNCTION interview_owner_immutable();
CREATE TRIGGER access_grant_owner_immutable BEFORE UPDATE ON access_grant FOR EACH ROW EXECUTE FUNCTION interview_owner_immutable();
CREATE FUNCTION interview_source_approval() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM access_grant g JOIN note_version v ON v.org_id=g.org_id AND v.id=NEW.source_note_version_id WHERE g.org_id=NEW.org_id AND g.id=NEW.grant_id AND v.employee_id=NEW.employee_id AND v.category=NEW.source_category AND v.status='published' AND ((g.capability='note.publish' AND g.category IN('shared','manager_private','hr_confidential')) OR (g.capability='action.write' AND g.category='shared')) AND g.purpose='interview_followup' AND g.scope_kind='employee' AND g.employee_id=NEW.employee_id AND (g.object_kind IS NULL OR g.object_employee_id=NEW.employee_id)) OR (SELECT count(*) FROM access_grant_source_approval WHERE org_id=NEW.org_id AND grant_id=NEW.grant_id)>=10 THEN RAISE EXCEPTION 'invalid source approval' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_source_approval BEFORE INSERT ON access_grant_source_approval FOR EACH ROW EXECUTE FUNCTION interview_source_approval();
CREATE FUNCTION interview_source_limit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.owner_note_version_id IS NOT NULL AND (SELECT count(*) FROM source_reference WHERE org_id=NEW.org_id AND owner_note_version_id=NEW.owner_note_version_id)>=10) OR (NEW.owner_action_event_id IS NOT NULL AND (SELECT count(*) FROM source_reference WHERE org_id=NEW.org_id AND owner_action_event_id=NEW.owner_action_event_id)>=10) THEN RAISE EXCEPTION 'too many sources' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_source_limit BEFORE INSERT ON source_reference FOR EACH ROW EXECUTE FUNCTION interview_source_limit();
CREATE FUNCTION interview_transition_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='scheduled' AND (NEW.status IN('scheduled','in_progress','cancelled') OR (NEW.status='completed' AND NEW.backfilled=true))) OR (OLD.status='in_progress' AND NEW.status IN('in_progress','completed','cancelled'))) OR (NEW.backfilled IS DISTINCT FROM OLD.backfilled AND NOT (OLD.backfilled=false AND NEW.backfilled=true AND OLD.status='scheduled' AND NEW.status='completed')) OR (OLD.actual_started_at IS NOT NULL AND NEW.actual_started_at IS DISTINCT FROM OLD.actual_started_at) OR (OLD.actual_ended_at IS NOT NULL AND NEW.actual_ended_at IS DISTINCT FROM OLD.actual_ended_at) THEN RAISE EXCEPTION 'invalid interview transition' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_transition_guard BEFORE UPDATE ON interview FOR EACH ROW EXECUTE FUNCTION interview_transition_guard();
CREATE FUNCTION action_transition_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='todo' AND NEW.status IN('in_progress','done','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN('done','cancelled'))) THEN RAISE EXCEPTION 'invalid action transition' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER action_transition_guard BEFORE UPDATE ON action_item FOR EACH ROW EXECUTE FUNCTION action_transition_guard();
CREATE UNIQUE INDEX interview_event_phase ON interview_event(org_id,interview_id,(CASE WHEN status IN('completed','cancelled') THEN 'terminal' ELSE status END));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_action_check;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_action_check CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_check2;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_check2 CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL));
